Definition xinside_numQ (br : option (Z * Z)) (bc : bctx) (b1 : expr) (k1 : Z) (n1 : expr) (b2 : expr) (k2 : Z) (n2 : expr) : bool :=
  match xloB bc b2, xhiB bc b2 with
  | Some lo2, Some hi2 =>
      if Z.eqb lo2 hi2 then
        match br, xhiB bc n1, xloB bc n2 with
        | Some (lo1, hi1), Some h1, Some l2 => Z.leb (lo2 + k2) (lo1 + k1) && Z.leb (hi1 + k1 + h1) (lo2 + k2 + l2)
        | _, _, _ => false
        end
      else false
  | _, _ => false
  end.
Lemma xinside_numQ_eq : forall bc b1 k1 n1 b2 k2 n2,
  xinside_numQ (base_rangeB bc b1) bc b1 k1 n1 b2 k2 n2 = xinside_numB bc b1 k1 n1 b2 k2 n2.
Proof.
