Definition xinsideQ (br : option (Z * Z)) (bc : bctx) (b1 : expr) (k1 : Z) (n1 : expr) (b2 : expr) (k2 : Z) (n2 : expr) : bool :=
  if xinside_andB bc b1 k1 n1 b2 k2 n2 then true else
  if shares_var b1 b2 then xinside0B bc b1 k1 n1 b2 k2 n2
  else if novars b2 then
    (if xinside_numQ br bc b1 k1 n1 b2 k2 n2 then true
     else if novars n1 then false else xinside0B bc b1 k1 n1 b2 k2 n2)
  else false.
Lemma xinsideQ_eq : forall bc b1 k1 n1 b2 k2 n2,
  xinsideQ (base_rangeB bc b1) bc b1 k1 n1 b2 k2 n2 = xinsideB bc b1 k1 n1 b2 k2 n2.
Proof.
