Definition kdisj_candQ (b1 b2 : expr) (K : kentry) : bool :=
  match K with
  | KDisj c1 _ c2 _ =>
      if (if shares_var b1 (a_base c1) then shares_var b2 (a_base c2) else false) then true
      else (if shares_var b1 (a_base c2) then shares_var b2 (a_base c1) else false)
  | _ => false
  end.
